contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take an amount param to send as msg.value to c.play
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        // Read observable before-state
        uint pot_before = c.pot(); if (__ESBMC_reverted()) return;

        // Perform the call and record whether it reverted
        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint pot_after = c.pot(); if (__ESBMC_reverted()) return;

        // The contract C requires msg.value == TICKET_AMOUNT else it reverts.
        // If the call reverted, pot must be unchanged. Otherwise, after a successful play,
        // either the random branch lost (pot increased by amount) or won (pot reset to 0).
        assert( (reverted && pot_after == pot_before)
                || (!reverted && (pot_after == pot_before + amount || pot_after == 0)) );
    }

    receive() external payable {}
}

